    switch s {
    case .idle: return "Tap to load"
    case .loading(let p): return "Loading \(Int(p * 100))%"
    case .loaded(let rows) where rows.isEmpty: return "Nothing here"
    case .loaded(let rows): return "\(rows.count) rows"
    case .failed(let message): return "Error: \(message)"
