func square(_ n: Int) async throws -> Int {
    try await Task.sleep(for: .milliseconds(100 * n))
    try Task.checkCancellation()
    return n * n
}

func sumOfSquares(_ ns: [Int]) async throws -> Int {
    try await withThrowingTaskGroup(of: Int.self) { group in
        for n in ns { group.addTask { try await square(n) } }
        var total = 0
        for try await value in group { total += value }  // completion order
        return total
    }
}

