final class Job { var log: [String] = [] }   // non-Sendable

actor Worker {
    private var jobs: [Job] = []
    func enqueue(_ job: sending Job) {        // caller gives the job up
        job.log.append("queued")
        jobs.append(job)
    }
    var count: Int { jobs.count }
}

func makeAndSend(to worker: Worker) async {
    let job = Job()                           // disconnected region
    job.log.append("created")
    await worker.enqueue(job)                 // OK: transferred
    // print(job.log)                         // error: 'job' used after being sent
}

func runOnCaller(_ a: isolated Worker) -> Int {  // runs on the actor passed in
    a.count                                   // no await needed
}

let w = Worker()
await makeAndSend(to: w)
print(await runOnCaller(w))                   // 1

final class Storage {
    var values: [Int]
    init(_ v: [Int]) { values = v }
