struct TempFile: ~Copyable {
    let fd: Int32
    init(fd: Int32) { self.fd = fd; print("open", fd) }
    borrowing func write(_ s: String) { print("write \(s) to", fd) }

    consuming func persist() -> Int32 {
        let kept = fd
        discard self                  // skip deinit: file is kept
        return kept
    }
    deinit { print("delete", fd) }
}

func log(_ f: borrowing TempFile) { f.write("log") }

do {
    let a = TempFile(fd: 3)           // open 3
    log(a)                            // write log to 3
    let b = a                         // move, not copy
    // a.write("x")                   // error: 'a' used after consume
    _ = b
}                                     // delete 3

let kept = TempFile(fd: 4).persist()
print("kept", kept)                   // open 4, kept 4 (no delete)

